import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"周易集注 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"周易集注 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"zh/classics/jizhu/013.md","filePath":"zh/classics/jizhu/013.md"}'),h={name:"zh/classics/jizhu/013.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>小者阴也，畜者止也，干下巽上，以阴畜阳，又一阴居四，上下五阳，皆其所畜，以小畜大，故为小畜。又畜之未极，阳犹尚往，亦小畜也。《序卦》：“比必有所畜，故受之以小畜。”所以次比。</p><p>中爻离错坎，云之象。中爻兑，西之象。下卦干，郊之象。详见需卦，凡云自西而来东者，水生木泄其气，故无雨。</p><p>小畜亨，然其所以亨者，以畜未极，而施未行也，故有密云不雨，自我西郊之象，故占者亨。</p><p>《彖》曰，小畜，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也。自我西郊，施未行也。(施始跂反)</p><p>以卦综卦德释卦名卦辞，得位者，八卦正位，巽在内也。本卦与履相综，故孔子《杂卦》曰：“小畜寡也，履不处也。”履之三爻阴居阳位，不得其位，往而为小畜之四，则得位矣，故曰“柔得位而上下应之”，上下者五阳也，以柔得位，而上下应之，则五阳皆四所畜矣，以小畜大，故曰小畜。内健，则此心果决，而能胜其私，外巽则见事详审，而不至躁妄。又二五刚居中位，则阳有可为之势，可以伸其必为之志矣。阳性上行，故曰志行，乃亨者，言阳为阴所畜，宜不亨矣。以健而巽，刚居中而志行，则阳犹可亨也。往者阳往，施者阴施，言畜之未极，阳气犹上往，而阴不能止也，惟阳上往，所以阴泽不能施行而成雨 。</p><h3 id="《象》曰-风行天上-小畜。君子以懿文德。" tabindex="-1">《象》曰：风行天上，小畜。君子以懿文德。 <a class="header-anchor" href="#《象》曰-风行天上-小畜。君子以懿文德。" aria-label="Permalink to “《象》曰：风行天上，小畜。君子以懿文德。”">​</a></h3><p>懿美也，巽顺，懿美之象。三干，阳德之象，中爻离文之象。以道而见诸躬行曰道德，见诸威仪文辞曰文德。风行天上，有气而无质，能畜而不能久，曰小畜。君子大则道德，小则文德，故体之以美其文德之小，曰文而必曰德者，见文乃德之辉也，非粉饰也。</p><p>初九，复自道，何其咎，吉。</p><p>自下升上曰复，归还之意。阳本在上之物，志欲上进，而为阴所畜止，故曰复。自者由也，道者以正道也，言进于上，乃阳之正道也。何其咎，见其本无咎也。复卦不远复，休复者，乃六阴已极之时，喜阳之复生于下，此卦之复自道。牵复者，乃一阴得位之时，喜阳之复升于上。</p><p>初九干体，居下得正，虽与四阴为正应，而能守正，不为四所畜，故有复自道之象。占者如是，则无咎而吉矣。</p><h3 id="《象》曰-复自道-其义吉也。" tabindex="-1">《象》曰：复自道，其义吉也。 <a class="header-anchor" href="#《象》曰-复自道-其义吉也。" aria-label="Permalink to “《象》曰：复自道，其义吉也。”">​</a></h3><p>在下而畜于上之阴者，势也;不为阴所畜而复于上者，理也。阳不为阴畜，乃理之自吉者，故曰其义吉。</p><p>九二，牵复，吉。</p><p>九二渐近于阴，若不能复矣。然九二刚中，则不过刚，而能守已相时，故亦复。与初二爻并复，有牵连而复之象。占者如是，则吉矣。三阳同体，故曰牵，故夬卦亦曰牵，程传，谓二五牵复，本义谓初，观小象亦字，则本义是。</p><h3 id="《象》曰-牵复在中-亦不自失也。" tabindex="-1">《象》曰：牵复在中，亦不自失也。 <a class="header-anchor" href="#《象》曰-牵复在中-亦不自失也。" aria-label="Permalink to “《象》曰：牵复在中，亦不自失也。”">​</a></h3><p>在中者，言阳刚居中也。亦者，承初爻之辞。言初九之复自道者，以其刚正，不为阴所畜，不自失也。九二刚中牵复，亦不自失也，言与初九同也。</p><p>九三，舆说辐，夫妻反目。(说音脱)</p><p>舆脱去其辐，则不能行，干错坤舆之象也。变兑为毁[折，脱辐之象也，脱辐非恶意，彼此相脱，不肯行也，干]*为夫，长女为妻，反目者，反转其目，不相对视也。中爻离为目，巽多白眼，反目之象也。三四初时阴阳相比而悦，及变兑为口舌，巽性进退不果，又妻乘其夫，妻居其外，夫反在内，则三反见制于四，不能正室，而反目矣，盖阳性终不可畜，所以小畜止能畜得九三一爻，诸爻皆不能畜，然亦三之自取也。</p><p>注*：括号中的文字四库全书版缺，据慈恩本补。</p><p>九三比阴，阴阳相悦，必苟合矣。为四畜止不行，故有舆脱辐之象。然三过刚不中，锐于前进。四性入坚于畜止，不许前进。三反见制于四，不能正室矣。故又有反目之象，其象如此，而占者之凶可知矣。</p><h3 id="《象》曰-夫妻反目-不能正室也。" tabindex="-1">《象》曰：夫妻反目，不能正室也。 <a class="header-anchor" href="#《象》曰-夫妻反目-不能正室也。" aria-label="Permalink to “《象》曰：夫妻反目，不能正室也。”">​</a></h3><p>室者闺门也，正者，男正位乎外，女正位乎内也。三四苟合，岂能正室，所以反目。故归妹大《象》曰，君子以永终知敝。</p><p>六四，有孚，血去惕出，无咎。(去上声)</p><p>[五阳皆实，一阴中虚，孚信虚中之象也。此爻离错坎，]*坎为血，血之象也。血去者，去其体之见伤也，又为加忧，惕之象也，惕出者，出其心之见惧也，曰去曰出者，以变爻言也，盖本爻未变错坎，有血惕之象，既变，则成纯干矣，岂有血惕，所以血去惕出也，本卦以小畜大，四为畜之主，近乎其五，盖畜君者也，畜止其君之欲，岂不伤害忧惧，盖畜有三义，畜之不善者，小人而羁縻君子是也，畜之善者，此爻是也。</p><p>注*：四库全书版缺，据慈恩本补。</p><p>六四近五，当畜其五者也。五居尊位，以阴畜之，未免伤害忧惧。然柔顺得正，乃能有孚诚信。以上合乎五之志，故有血去惕出之象。占者能如是诚信，斯无咎矣。</p><h3 id="《象》曰-有孚惕出-上合志也。" tabindex="-1">《象》曰：有孚惕出，上合志也。 <a class="header-anchor" href="#《象》曰-有孚惕出-上合志也。" aria-label="Permalink to “《象》曰：有孚惕出，上合志也。”">​</a></h3><p>上合志者，以其有孚诚信也。</p><p>九五，有孚挛如，富以其邻。</p><p>本卦大象中虚，而九五中正，故有孚诚信，挛者，挛缀也，缀者缉也续也，皆相连之意，即九二之牵也。谓其皆阳之类，所以牵连相从也。巽为绳，挛之象也。又为近市利三倍，富之象也。故家人亦曰“富家大吉”。五居尊位，如富者，有财可与邻共之也。以者，左右之也。以其邻者，援挽同德，与之相济也。君子为小人所困，正人为邪党所厄，则在下者必攀挽于上，期于同进;在上者，必援引于下，与之协力，故二牵而五挛，本卦虽以阴畜阳，初二皆牵复吉，不为阴所畜。彖曰：刚中而志行，乃亨。刚中志行，正在此爻故亨。若旧注以三爻同力畜干，则助小人以畜君子，阳岂得亨，非圣人作易之意矣。一阴五阳，君子多于小人，所以初二五皆不能畜。</p><p>九五居尊，势有可为，以九二同德为辅佐。当小人畜止之时，刚中志行，故有有孚挛如，富以其邻，小人不得畜止之象。占者有孚，亦如是也。</p><h3 id="《象》曰-有孚挛如-不独富也。" tabindex="-1">《象》曰：有孚挛如，不独富也。 <a class="header-anchor" href="#《象》曰-有孚挛如-不独富也。" aria-label="Permalink to “《象》曰：有孚挛如，不独富也。”">​</a></h3><p>言有孚，则人皆牵挛而从之矣，不必有其富也。今五居尊位，既富矣，而又有孚，故曰不独富。</p><p>上九，既雨既处，尚德载，妇贞厉，月几望，君子征凶。</p><p>上九变坎为雨，雨之象也。处者止也，巽性既进而退，巽风吹散其雨，既雨既止之象也。雨既止，可尚往矣。尚德载者，下三阳为德，坎为舆，成需，即需上六，不速之客三人来也。载者，积三阳而载之也，故曰积德载。此言阳尚往也，水火乃相错之卦，火天大有，曰大车以载。《象》曰：积中不败，则坎车积三阳，载之上往也明矣。巽妇畜干之夫，以顺为正，巽本顺而正者也，今变坎，失巽顺而为险陷，危厉之道也，故始贞而今厉矣。坎为月，中爻离为日，日月之象也。巽错震，中爻兑，震东兑西，日月相望之象也。言阴盛也，易中言月几望者三，皆对阳而言，中孚言从乎阳，归妹言应乎阳，此则抗乎阳也。三阳有乾德，故曰君子。巽性进退不果，本疑惑之人，今变坎陷，终必疑君子之进。畜止而陷之，故征凶。</p><p>畜已终矣，阴终不能畜阳，故有雨止阳往之象。畜者虽贞，亦厉之道也，然阴既盛抗阳，则君子亦不可往矣。两有所成也，故其象占如此。阳终不为阴所畜，故杂卦曰，小畜寡也。观寡字，可知矣。</p><h3 id="《象》曰-既雨既处-德积载也。君子征凶-有所疑也。" tabindex="-1">《象》曰：既雨既处，德积载也。君子征凶，有所疑也。 <a class="header-anchor" href="#《象》曰-既雨既处-德积载也。君子征凶-有所疑也。" aria-label="Permalink to “《象》曰：既雨既处，德积载也。君子征凶，有所疑也。”">​</a></h3><p>阳德积而尚往，故贞厉，阴终疑阳之进而畜之，故征凶。</p>',39)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
